import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Science Working Group 2020-11-25","description":"","frontmatter":{"title":"Ceph Science Working Group 2020-11-25","date":"2020-11-25T00:00:00.000Z","updated":"2020-11-26T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Science_Working_Group_2020-11-25.md","filePath":"posts/2020/Ceph_Science_Working_Group_2020-11-25.md","lastUpdated":1780459816000}'),o={name:"posts/2020/Ceph_Science_Working_Group_2020-11-25.md"};function r(n,e,s,h,p,u){return l(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次Ceph Science Working Group会议讨论了Ceph存储系统在近期遇到的问题、技术挑战及解决方案。会议持续了一个小时，内容自由，涉及多个主题。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Ceph集群问题</strong></p><ul><li>讨论了替换S3集群硬件时PG迁移和删除效率问题，以及BlueFS Buffered IO对稳定集群的帮助。</li><li>Igor正在准备一个补丁来解决PG删除效率低的问题。</li><li>提到了Nautilus版本中内存泄漏和稳定性问题，以及Beast协议相关的问题。</li></ul></li><li><p><strong>Ceph版本更新和升级</strong></p><ul><li>讨论了从旧版本升级到Octopus版本的体验，包括内存泄漏和稳定性问题。</li><li>提到了Beast协议的问题和对Rados Gateway内存使用的讨论。</li></ul></li><li><p><strong>Ceph性能和配置</strong></p><ul><li>讨论了多MDS的使用情况和性能问题，以及BlueStore的配置和性能优化。</li><li>提到了BlueFS和BlueStore allocator的改进。</li></ul></li><li><p><strong>Ceph集群管理和运维</strong></p><ul><li>讨论了限制Rados Gateway内存使用和网络架构中使用Rados Gateway的策略。</li><li>提到了从直接使用Librados转向使用Rados Gateway的可能性。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>关注Igor的PG删除补丁和BlueFS Buffered IO的启用情况。</li><li>测试和验证Beast协议问题，并考虑回退到CivetWeb。</li><li>监控和优化Rados Gateway的内存使用。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>关注Ceph版本更新和补丁发布，特别是与内存管理和性能优化相关的更新。</li><li>测试和部署新的BlueStore配置和优化。</li><li>监控和调整Rados Gateway的配置。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了使用InfiniBand网络的可能性，但认为以太网已经足够满足需求。</li><li>提到了备份大型Ceph集群的挑战，特别是对于运行Oracle数据库的集群。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论未来可能的技术升级和优化方向后结束。下一次会议计划在明年一月的第四个星期三举行。</p><h4 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h4><p>本次会议重点关注了Ceph集群的稳定性、性能优化和版本升级。会议讨论了多个与Ceph集群管理和运维相关的问题，并制定了后续行动计划。</p>',15)])])}const _=a(o,[["render",r]]);export{c as __pageData,_ as default};
